const body = $input.first().json.body || {};

if (body.event !== 'vehicle_expense_limit_reached') {
  throw new Error('Evento não reconhecido.');
}

if (
  typeof body.vehicle_name !== 'string' ||
  !body.vehicle_name.trim() ||
  typeof body.total_expenses_cents !== 'number' ||
  typeof body.limit_cents !== 'number' ||
  !Number.isSafeInteger(body.total_expenses_cents) ||
  !Number.isSafeInteger(body.limit_cents) ||
  body.total_expenses_cents < body.limit_cents ||
  body.limit_cents <= 0
) {
  throw new Error('Dados do alerta inválidos.');
}

const currency = cents =>
  (cents / 100).toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  });

const vehicle = body.vehicle_name.trim();

const subject = `LM Gestão | Alerta de limite de despesas - ${vehicle}`;

const message = `
LM VEÍCULOS - ALERTA DE DESPESAS

Atenção! Um veículo atingiu o limite de despesas estabelecido.

Veículo: ${vehicle}

Total de despesas: ${currency(body.total_expenses_cents)}

Limite configurado: ${currency(body.limit_cents)}

Recomendamos verificar os gastos registrados no painel LM Gestão para acompanhar os custos do veículo.

Atenciosamente,
Sistema LM Gestão

Esta é uma notificação automática. Não é necessário responder.
`.trim();

return [
  {
    json: {
      subject,
      message,
      vehicle_id: body.vehicle_id || ''
    }
  }
];
